const topicBatch = $node['Load Topic Data'].json[0];
const request = $node['Research Request Trigger'].json;

let selectedTopic;

if (request.fast_track && request.priority_topics && request.priority_topics.length > 0) {
  // Fast track mode - use the specific topic
  selectedTopic = request.priority_topics[0];
} else {
  // Normal mode - select highest priority unresearched topic
  const topics = JSON.parse(topicBatch.topics_data);
  selectedTopic = topics.find(t => !t.research_status || t.research_status === 'pending') || topics[0];
}

return {
  batch_id: topicBatch.id,
  selected_topic: selectedTopic,
  research_id: `research_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
  fast_track: request.fast_track || false,
  research_depth: request.research_depth || 'comprehensive'
};

const topic = $node['Select Next Research Topic'].json.selected_topic;
const webResearch = JSON.parse($node['Conduct Web Research'].json.choices[0].message.content);
const industryAnalysis = JSON.parse($node['Industry Context Analysis'].json.choices[0].message.content);
const internalKnowledge = $node['Query Internal Knowledge'].json.matches || [];

// Compile comprehensive research
const researchFindings = {
  topic_info: {
    title: topic.topic_title,
    description: topic.topic_description,
    content_angle: topic.content_angle,
    target_audience: topic.target_audience_segment
  },

  web_research: {
    statistics: webResearch.statistics || [],
    expert_insights: webResearch.expert_insights || [],
    case_studies: webResearch.case_studies || [],
    supporting_evidence: webResearch.supporting_evidence || [],
    trends: webResearch.trends || [],
    sources: webResearch.sources || []
  },

  industry_context: {
    market_landscape: industryAnalysis.market_landscape || {},
    competitive_analysis: industryAnalysis.competitive_analysis || {},
    audience_insights: industryAnalysis.audience_insights || {},
    technology_trends: industryAnalysis.technology_trends || {},
    strategic_recommendations: industryAnalysis.strategic_recommendations || []
  },

  internal_knowledge: {
    relevant_content: internalKnowledge.slice(0, 5).map(match => ({
      content: match.metadata.text,
      source: match.metadata.source,
      relevance: match.score,
      content_type: match.metadata.content_type
    })),
    knowledge_gaps: [],
    internal_expertise: []
  },

  content_brief: {
    key_messages: [],
    supporting_points: [],
    data_points: [],
    expert_quotes: [],
    examples_to_include: [],
    sources_to_cite: [],
    content_structure: {
      introduction: {
        hook: '',
        context: '',
        thesis: ''
      },
      main_sections: [],
      conclusion: {
        summary: '',
        call_to_action: topic.call_to_action || '',
        next_steps: []
      }
    }
  },

  research_metadata: {
    research_id: $node['Select Next Research Topic'].json.research_id,
    research_depth: $node['Select Next Research Topic'].json.research_depth,
    research_date: new Date().toISOString(),
    sources_count: (webResearch.sources || []).length,
    confidence_score: 8.5, // Algorithm could assess source quality
    completeness_score: 9.0
  }
};

// Extract key insights for content brief
if (webResearch.statistics && webResearch.statistics.length > 0) {
  researchFindings.content_brief.data_points = webResearch.statistics.slice(0, 5);
}

if (webResearch.expert_insights && webResearch.expert_insights.length > 0) {
  researchFindings.content_brief.expert_quotes = webResearch.expert_insights.slice(0, 3);
}

if (webResearch.case_studies && webResearch.case_studies.length > 0) {
  researchFindings.content_brief.examples_to_include = webResearch.case_studies.slice(0, 2);
}

// Generate content structure
researchFindings.content_brief.content_structure.main_sections = topic.key_points.map(point => ({
  section_title: point,
  key_points: [],
  supporting_data: [],
  examples: []
}));

return researchFindings;

const request = $input.first().json;

// Process different types of knowledge updates
const knowledgeTypes = {
  'research_findings': {
    source: request.research_id,
    content: request.research_data,
    type: 'research'
  },
  'industry_report': {
    source: request.report_url,
    content: request.report_summary,
    type: 'industry_data'
  },
  'expert_interview': {
    source: request.expert_name,
    content: request.interview_transcript,
    type: 'expert_insight'
  },
  'case_study': {
    source: request.case_study_title,
    content: request.case_study_data,
    type: 'case_study'
  }
};

const knowledgeData = knowledgeTypes[request.knowledge_type] || {
  source: 'manual_entry',
  content: request.content,
  type: 'general'
};

return {
  knowledge_id: `kb_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
  knowledge_type: request.knowledge_type,
  source: knowledgeData.source,
  content: knowledgeData.content,
  metadata: {
    added_by: request.added_by || 'research_agent',
    confidence_level: request.confidence_level || 'high',
    expiration_date: request.expiration_date,
    tags: request.tags || [],
    category: knowledgeData.type
  },
  timestamp: new Date().toISOString()
};
